mkdir -p /tmp/rls-test && cat > /tmp/rls-test/stubs.sql <<'EOF'
-- Minimal stand-ins for Supabase's auth schema and roles.
create role anon nologin;
create role authenticated nologin;
grant usage on schema public to anon, authenticated;
create schema auth;
create table auth.users (id uuid primary key default gen_random_uuid());
create function auth.uid() returns uuid language sql stable as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
grant usage on schema auth to anon, authenticated;
grant execute on function auth.uid() to anon, authenticated;
EOF
cat > /tmp/rls-test/test.sql <<'EOF'
\set ON_ERROR_STOP 0
-- Fixed user IDs
\set A '''00000000-0000-0000-0000-00000000000a'''
\set B '''00000000-0000-0000-0000-00000000000b'''
\set C '''00000000-0000-0000-0000-00000000000c'''
\set T1 '''00000000-0000-0000-0000-000000000101'''
\set T2 '''00000000-0000-0000-0000-000000000102'''
\set P1 '''00000000-0000-0000-0000-000000000201'''
\set P2 '''00000000-0000-0000-0000-000000000202'''

insert into auth.users (id) values (:A), (:B), (:C);
insert into public.teams (id, name) values (:T1, 'one'), (:T2, 'two');
insert into public.team_members (team_id, user_id, role) values
  (:T1, :A, 'admin'), (:T1, :B, 'member'), (:T2, :C, 'admin');
insert into public.projects (id, team_id, name) values (:P1, :T1, 'p1'), (:P2, :T2, 'p2');

-- Switch to a role and identity. Each check runs in its own transaction.
create or replace function pg_temp.as_user(uid text, r text) returns void language plpgsql as $$
begin
  execute format('set role %I', r);
  perform set_config('request.jwt.claim.sub', uid, false);
end $$;

\echo '== A (admin T1, member of nothing else)'
set role authenticated; select set_config('request.jwt.claim.sub', :A, false);
select 'A teams' as check, count(*) from public.teams;           -- expect 1
select 'A team_members' as check, count(*) from public.team_members; -- expect 2
select 'A projects' as check, count(*) from public.projects;     -- expect 1
select 'A view' as check, count(*) from public.project_overview; -- expect 1
insert into public.projects (team_id, name) values (:T1, 'new');  -- expect ok
insert into public.projects (team_id, name) values (:T2, 'bad'); -- expect ERROR (RLS)
update public.projects set team_id = :T2 where id = :P1;          -- expect ERROR (RLS)
update public.projects set name = 'renamed' where id = :P1;       -- expect 1 row
delete from public.team_members where team_id = :T1 and user_id = :B; -- expect 1
insert into public.team_members (team_id, user_id, role) values (:T1, :B, 'member'); -- expect ok
insert into public.team_members (team_id, user_id, role) values (:T2, :A, 'member'); -- expect ERROR
delete from public.projects where id = :P2;                       -- expect 0 rows
reset role;

\echo '== B (member of T1, not admin)'
set role authenticated; select set_config('request.jwt.claim.sub', :B, false);
select 'B teams' as check, count(*) from public.teams;           -- expect 1
select 'B projects' as check, count(*) from public.projects;     -- expect 2 (P1 + new)
select 'B view' as check, count(*) from public.project_overview; -- expect 2
insert into public.projects (team_id, name) values (:T1, 'nope'); -- expect ERROR
update public.projects set name = 'hacked' where id = :P1;        -- expect 0 rows
delete from public.projects where id = :P1;                       -- expect 0 rows
insert into public.team_members (team_id, user_id, role) values (:T1, :C, 'member'); -- expect ERROR
delete from public.team_members where team_id = :T1 and user_id = :A; -- expect 0 rows
update public.teams set name = 'x' where id = :T1;               -- expect 0 rows
reset role;

\echo '== C (admin T2 only)'
set role authenticated; select set_config('request.jwt.claim.sub', :C, false);
select 'C teams' as check, count(*) from public.teams;           -- expect 1 (T2)
select 'C team_members' as check, count(*) from public.team_members; -- expect 1
select 'C projects' as check, count(*) from public.projects;     -- expect 1 (P2)
update public.projects set name = 'x' where id = :P1;            -- expect 0 rows
delete from public.projects where id = :P1;                      -- expect 0 rows
insert into public.projects (team_id, name) values (:T1, 'x');   -- expect ERROR
reset role;

\echo '== Signed out (anon)'
set role anon; select set_config('request.jwt.claim.sub', '', false);
select 'anon teams' as check, count(*) from public.teams;        -- expect ERROR permission denied
select 'anon projects' as check, count(*) from public.projects;  -- expect ERROR permission denied
select 'anon view' as check, count(*) from public.project_overview; -- expect ERROR permission denied
reset role;

\echo '== Signed-in with no sub (auth.uid() null)'
set role authenticated; select set_config('request.jwt.claim.sub', '', false);
select 'null-uid teams' as check, count(*) from public.teams;    -- expect 0
select 'null-uid projects' as check, count(*) from public.projects; -- expect 0
reset role;
EOF
cd /tmp/rls-test && docker rm -f rls-pg >/dev/null 2>&1; docker run -d --name rls-pg -e POSTGRES_PASSWORD=pw -p 55432:5432 postgres:16 >/dev/null && for i in $(seq 1 30); do docker exec rls-pg pg_isready -U postgres >/dev/null 2>&1 && break; sleep 1; done; echo ready

